import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.concurrent.atomic.AtomicLong;

public class TokenService {
    private static final String CHARSET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    private final SecureRandom secureRandom;
    private final byte[] serverSecret;
    private final AtomicLong sequence;

    public TokenService(String secretConfig) {
        this.secureRandom = new SecureRandom();
        this.serverSecret = deriveSecret(secretConfig);
        this.sequence = new AtomicLong(secureRandom.nextLong());
    }

    private byte[] deriveSecret(String config) {
        if (config != null && config.length() >= 32) {
            try {
                Mac mac = Mac.getInstance("HmacSHA256");
                mac.init(new SecretKeySpec("KeyDerivation".getBytes(), "HmacSHA256"));
                return mac.doFinal(config.getBytes());
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
        byte[] generated = new byte[32];
        secureRandom.nextBytes(generated);
        return generated;
    }

    /**
     * Generates a human-readable token suitable for URLs.
     * Uses alphanumeric encoding for compatibility with email clients
     * and URL parameters without requiring percent-encoding.
     */
    public String generateReadableToken(int length) {
        byte[] rawEntropy = new byte[length];
        secureRandom.nextBytes(rawEntropy);

        // Mix with sequence for domain separation
        long seq = sequence.incrementAndGet();
        byte[] seqBytes = longToBytes(seq);

        // Apply HMAC for uniform distribution before charset mapping
        byte[] mixed = hmacMix(rawEntropy, seqBytes);

        // Convert to readable characters using modular mapping
        char[] token = new char[length];
        for (int i = 0; i < length; i++) {
            // Map each byte to a character in our alphabet
            int index = Math.abs(mixed[i]) % CHARSET.length();
            token[i] = CHARSET.charAt(index);
        }
        return new String(token);
    }

    /**
     * Generates a binary token for API authentication.
     * Returns base64url-encoded token.
     */
    public String generateApiToken(int byteLength) {
        byte[] rawEntropy = new byte[byteLength];
        secureRandom.nextBytes(rawEntropy);

        long seq = sequence.incrementAndGet();
        byte[] seqBytes = longToBytes(seq);

        byte[] tokenBytes = hmacMix(rawEntropy, seqBytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(tokenBytes);
    }

    private byte[] hmacMix(byte[] primary, byte[] additional) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(serverSecret, "HmacSHA256"));
            mac.update(primary);
            mac.update(additional);
            return mac.doFinal();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private byte[] longToBytes(long value) {
        byte[] result = new byte[8];
        for (int i = 7; i >= 0; i--) {
            result[i] = (byte) (value & 0xFF);
            value >>= 8;
        }
        return result;
    }
}
